module tb_TopModule;

    reg        clk;
    reg        areset;

    reg        predict_valid;
    reg  [6:0] predict_pc;
    wire       predict_taken;
    wire [6:0] predict_history;

    reg        train_valid;
    reg        train_taken;
    reg        train_mispredicted;
    reg  [6:0] train_history;
    reg  [6:0] train_pc;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .predict_valid(predict_valid),
        .predict_pc(predict_pc),
        .predict_taken(predict_taken),
        .predict_history(predict_history),
        .train_valid(train_valid),
        .train_taken(train_taken),
        .train_mispredicted(train_mispredicted),
        .train_history(train_history),
        .train_pc(train_pc)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        areset = 1;
        predict_valid = 0;
        predict_pc = 0;
        train_valid = 0;
        train_taken = 0;
        train_mispredicted = 0;
        train_history = 0;
        train_pc = 0;

        #12;
        areset = 0;
        #10;

        // Test 1: Predict with PC = 7'h10, GHR = 0. Index = 0x10 ^ 0 = 0x10.
        // PHT[0x10] is 2'b01 (weakly not taken). predict_taken should be 0.
        predict_valid = 1;
        predict_pc = 7'h10;
        #10;
        if (predict_taken !== 0 || predict_history !== 7'h0) begin
            $display("SELFTEST FAIL: Test 1 failed. taken=%b (exp 0), history=%h (exp 00)", predict_taken, predict_history);
            $finish;
        end
        // GHR should now be updated to {0[5:0], 0} = 0 (since predict_taken was 0).

        // Test 2: Train PHT[0x10] with taken=1, mispredicted=0.
        predict_valid = 0;
        train_valid = 1;
        train_pc = 7'h10;
        train_history = 7'h0;
        train_taken = 1;
        train_mispredicted = 0;
        #10;

        // Test 3: Predict again with PC = 7'h10, GHR = 0.
        // PHT[0x10] should now be 2'b10 (weakly taken), predict_taken should be 1.
        train_valid = 0;
        predict_valid = 1;
        predict_pc = 7'h10;
        #10;
        if (predict_taken !== 1 || predict_history !== 7'h0) begin
            $display("SELFTEST FAIL: Test 3 failed. taken=%b (exp 1), history=%h (exp 00)", predict_taken, predict_history);
            $finish;
        end
        // GHR updated to {0[5:0], 1} = 7'h01.

        // Test 4: Simultaneous train (mispredicted) and predict.
        // Train PC = 7'h10, history = 0, taken = 0, mispredicted = 1.
        // Predict PC = 7'h20, valid = 1.
        // Training takes precedence for GHR, so GHR should recover to {7'h0[5:0], 0} = 0.
        predict_valid = 1;
        predict_pc = 7'h20;
        train_valid = 1;
        train_pc = 7'h10;
        train_history = 7'h0;
        train_taken = 0;
        train_mispredicted = 1;
        #10;

        // Check if history became 0 (training precedence)
        predict_valid = 0;
        train_valid = 0;
        #2;
        if (predict_history !== 7'h0) begin // wait, predict_history output tracks GHR directly. Let's check GHR via predict_valid=1 with PC=0
            $display("SELFTEST FAIL: Test 4 failed. GHR recovery failed, history=%h (exp 0)", predict_history);
            // wait, predict_history output is `ghr`. Let's check ghr directly by issuing a predict.
        end

        // Let's do a clean check of GHR
        predict_valid = 1;
        predict_pc = 7'h0;
        #10;
        if (predict_history !== 7'h0) begin
            $display("SELFTEST FAIL: Test 4b failed. history=%h (exp 0)", predict_history);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

