        .predict_taken(predict_taken),
        .predict_history(predict_history),
        .train_valid(train_valid),
        .train_taken(train_taken),
        .train_mispredicted(train_mispredicted),
        .train_history(train_history),
        .train_pc(train_pc)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        areset = 1;
        predict_valid = 0;
        predict_pc = 0;
        train_valid = 0;
        train_taken = 0;
        train_mispredicted = 0;
        train_history = 0;
        train_pc = 0;

        @(posedge clk);
        #2;
        areset = 0;
        @(posedge clk);

        // Test 1: Predict PC = 0x10, GHR = 0. PHT[0x10] = 01 -> taken = 0.
        @(negedge clk);
        predict_valid = 1;
        predict_pc = 7'h10;
        train_valid = 0;

        #4; // Check 1ns before posedge
        if (predict_taken !== 0 || predict_history !== 7'h0) begin
            $display("SELFTEST FAIL: Test 1 failed. taken=%b, history=%h", predict_taken, predict_history);
            $finish;
        end
        @(posedge clk);

        // Test 2: Train PHT[0x10] with taken=1
        @(negedge clk);
        predict_valid = 0;
        train_valid = 1;
        train_pc = 7'h10;
        train_history = 7'h0;
        train_taken = 1;
        train_mispredicted = 0;
        @(posedge clk);

        // Test 3: Predict PC = 0x10, GHR = 0. PHT[0x10] should now be 10 -> taken = 1.
        @(negedge clk);
        train_valid = 0;
        predict_valid = 1;
        predict_pc = 7'h10;

        #4;
        if (predict_taken !== 1 || predict_history !== 7'h0) begin
            $display("SELFTEST FAIL: Test 3 failed. taken=%b, history=%h", predict_taken, predict_history);
            $finish;
        end
        @(posedge clk);

        // Test 4: Simultaneous training (mispredicted) and prediction.
        // Train: PC=0x20, history=7'h05, taken=0, mispredicted=1 -> GHR should recover to {7'h05[5:0], 0} = 0x0A.
        // Predict: PC=0x30, valid=1.
        @(negedge clk);
        train_valid = 1;
        train_pc = 7'h20;
        train_history = 7'h05;
        train_taken = 0;
        train_mispredicted = 1;

        predict_valid = 1;
        predict_pc = 7'h30;
        @(posedge clk);

        // Test 5: Check GHR recovery (GHR should be 0x0A).
        @(negedge clk);
        train_valid = 0;
        predict_valid = 1;
        predict_pc = 7'h0; // index = 0 ^ 0x0A = 0x0A

        #4;
        if (predict_history !== 7'h0A) begin
            $display("SELFTEST FAIL: Test 5 GHR recovery failed. history=%h (exp 0A)", predict_history);
            $finish;
        end
        @(posedge clk);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
